/// `import "fmt"` / `import f "fmt"` / `import ( a "x"; b "y" )`.
fn collect_imports(decl: &Node, source: &[u8], pending: &mut PendingFile, module_index: usize) {
    let line = line_of(decl);
    let mut cursor = decl.walk();
    for child in decl.children(&mut cursor) {
        match child.kind() {
            "import_spec" => emit_import_spec(&child, source, pending, module_index, line),
            "import_spec_list" => {
                let mut lc = child.walk();
                for spec in child.children(&mut lc) {
                    if spec.kind() == "import_spec" {
                        emit_import_spec(&spec, source, pending, module_index, line);
                    }
                }
            }
            _ => {}
        }
    }
}

fn emit_import_spec(
    spec: &Node,
    source: &[u8],
    pending: &mut PendingFile,
    module_index: usize,
    line: u32,
) {
    let path_lit = spec
        .child_by_field_name("path")
        .and_then(|n| node_text(&n, source))
        .map(|s| s.trim_matches('"').to_string());
    let Some(path) = path_lit else { return };
    if path.is_empty() {
        return;
    }
    // Leaf: explicit alias if present, else last `/` segment.
    let leaf = spec
        .child_by_field_name("name")
        .and_then(|n| node_text(&n, source))
        .filter(|n| *n != "_" && *n != ".")
        .map(str::to_string)
        .unwrap_or_else(|| path.rsplit('/').next().unwrap_or(&path).to_string());
    let to_path = Some(format!("{path}::*"));
    push_import(pending, module_index, leaf, to_path, line);
}

pub(crate) fn unacknowledged(&self) -> Result<Vec<(String, String)>, Unresolved> {
    let baseline = self.baseline.as_ref().map_err(Clone::clone)?;
    let mut remaining = Vec::new();
    for key in &self.removed {
        let symbol = baseline.symbol(key)?;
        if symbol.kind != "module" && !self.acknowledged.contains(key) {
            let file = &baseline.files[&key.0];
            let name = ancestry(file, key.1, baseline.deadline)?.join(".");
            remaining.push((key.0.clone(), name));
        }
    }
    remaining.sort();
    Ok(remaining)
}

pub(crate) fn accepts_file_removal(&self, file: &str) -> bool {
    let Ok(file) = normalize_file(file) else {
        return false;
    };
    if self.baseline.is_err() {
        return false;
    }
    let mut keys = self.removed.iter().filter(|key| key.0 == file).peekable();
    keys.peek().is_some() && keys.all(|key| self.acknowledged.contains(key))
}

